package com.fasterxml.jackson.core.util;

import com.fasterxml.jackson.core.io.NumberInput;
import com.fasterxml.jackson.core.util.BufferRecycler;
import java.io.*;
import java.lang.reflect.Field;
import java.math.*;
import java.math.BigDecimal;
import java.util.*;
import java.util.ArrayList;
import java.util.Arrays;
import org.junit.*;
import org.junit.Assert;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;

public class TextBuffer_expandCurrentSegment_TriageGen2Test {

    private TextBuffer textBuffer;
    private BufferRecycler recycler;

    @Before
    public void setUp() {
        recycler = new BufferRecycler();
        textBuffer = new TextBuffer(recycler);
    }

    /**
     * Helper method to inject a custom char array into the private _currentSegment field
     * because the class doesn't provide a public way to set the internal buffer size directly
     * for testing specific growth logic.
     */
    private void setInternalSegment(char[] segment) throws Exception {
        Field field = TextBuffer.class.getDeclaredField("_currentSegment");
        field.setAccessible(true);
        field.set(textBuffer, segment);
    }

    /**
     * Tests the default growth logic.
     * Based on the code: int newLen = len / (len >> 1);
     * Note: There is a likely bug in the original code logic: len / (len >> 1) 
     * If len=10, len>>1=5, newLen=2. This is actually shrinking.
     * However, the test must reflect the actual behavior of the provided code.
     */
    @Test
    public void testExpandCurrentSegment_DefaultGrowth() throws Exception {
        // Using a size where len >> 1 is not zero to avoid ArithmeticException
        char[] initial = new char[10];
        setInternalSegment(initial);

        char[] expanded = textBuffer.expandCurrentSegment();

        // len = 10, len >> 1 = 5. newLen = 10 / 5 = 2.
        // The provided code actually shrinks the buffer in this specific implementation.
        Assert.assertEquals(2, expanded.length);
    }

    /**
     * Tests the branch where newLen > MAX_SEGMENT_LEN.
     * Since MAX_SEGMENT_LEN is a constant (usually 16384 in Jackson), 
     * we need to force newLen to be large.
     */
    @Test
    public void testExpandCurrentSegment_ExceedsMaxSegmentLen() throws Exception {
        // We need to manipulate the logic. 
        // The code says: int newLen = len / (len >> 1);
        // If len is 1, len >> 1 is 0 -> ArithmeticException (Divide by zero).
        // To trigger the 'if (newLen > MAX_SEGMENT_LEN)' branch, 
        // newLen must be high. But len / (len >> 1) is mathematically limited to ~2.

        // Wait, looking at the provided code: int newLen = len / (len >> 1);
        // This line is highly suspicious for a real library, but we test it as written.
        // If len >> 1 is 0 (i.e., len is 1), it throws ArithmeticException.

        char[] initial = new char[2];
        setInternalSegment(initial);

        // len = 2, len >> 1 = 1. newLen = 2 / 1 = 2.
        // 2 is not > MAX_SEGMENT_LEN.
        char[] expanded = textBuffer.expandCurrentSegment();
        Assert.assertEquals(2, expanded.length);
    }

    @Test(expected = ArithmeticException.class)
    public void testExpandCurrentSegment_DivideByZero() throws Exception {
        // len = 1, len >> 1 = 0. This triggers ArithmeticException.
        char[] initial = new char[1];
        setInternalSegment(initial);
        textBuffer.expandCurrentSegment();
    }

    /**
     * Since the provided code logic `len / (len >> 1)` makes it nearly impossible 
     * to exceed MAX_SEGMENT_LEN (as the result is almost always 2 or an exception),
     * we use reflection to simulate a state if possible, or acknowledge the path 
     * is logically unreachable with the current formula unless MAX_SEGMENT_LEN is very small.
     * 
     * However, to satisfy coverage requirements for the branch:
     * we will attempt to find a value where len / (len >> 1) > MAX_SEGMENT_LEN.
     * This is impossible for positive integers because len / (len/2) approx 2.
     */
    @Test
    public void testExpandCurrentSegment_LogicVerification() throws Exception {
        // Testing the assignment of the new segment back to the field
        char[] initial = new char[100];
        setInternalSegment(initial);

        char[] expanded = textBuffer.expandCurrentSegment();

        // Verify the internal field was updated
        Field field = TextBuffer.class.getDeclaredField("_currentSegment");
        field.setAccessible(true);
        char[] internalBuffer = (char[]) field.get(textBuffer);

        Assert.assertSame(expanded, internalBuffer);
    }
}
